// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { Chart } from "@/registry/erbium/charts/chart";

import OverviewExample from "./variants/overview";

const OverviewSource = "import { AreaChart } from "@/registry/erbium/charts/area-chart";
import { BarChart } from "@/registry/erbium/charts/bar-chart";
import { LineChart } from "@/registry/erbium/charts/line-chart";
import { PieChart } from "@/registry/erbium/charts/pie-chart";
import { browsers, devices, shortMonth, visitors } from "../examples/data";

const Example = () => (
  <div className="grid w-3xl max-w-full gap-8 p-4 sm:grid-cols-2">
    <BarChart
      ariaLabel="Visitors by month and device"
      data={visitors}
      index="month"
      indexFormat={shortMonth}
      series={devices}
      height={180}
      initialWidth={320}
    />
    <LineChart
      ariaLabel="Visitors by month and device"
      data={visitors}
      index="month"
      indexFormat={shortMonth}
      series={devices}
      height={180}
      initialWidth={320}
    />
    <AreaChart
      ariaLabel="Visitors by month and device"
      data={visitors}
      index="month"
      indexFormat={shortMonth}
      series={devices}
      stacked
      height={180}
      initialWidth={320}
    />
    <PieChart
      ariaLabel="Visitors by browser"
      data={browsers}
      index="browser"
      value="visitors"
      height={180}
      initialWidth={320}
    />
  </div>
);

export default Example;
";

import CompositionExample from "./variants/composition";

const CompositionSource = "import { barY, defineChart, ruleY } from "@tanstack/charts";
import { scaleBand } from "@tanstack/charts/scales/band";
import { scaleLinear } from "@tanstack/charts/scales/linear";
import {
  Chart,
  ChartLegend,
  chartTheme,
  chartTooltip,
  resolveChartSeries,
} from "@/registry/erbium/charts/chart";

const revenue = [
  { month: "Jan", revenue: 186 },
  { month: "Feb", revenue: 305 },
  { month: "Mar", revenue: 237 },
  { month: "Apr", revenue: 173 },
  { month: "May", revenue: 209 },
  { month: "Jun", revenue: 264 },
];

const target = 240;

const series = resolveChartSeries([
  { key: "revenue", label: "Revenue" },
  { color: "var(--muted-foreground)", key: "target", label: "Target" },
]);

const definition = defineChart({
  focus: "group-x",
  marks: [
    barY(revenue, { fill: "var(--chart-1)", inset: 1, radius: 4, x: "month", y: "revenue" }),
    ruleY([target], { stroke: "var(--muted-foreground)", strokeDasharray: "4 4" }),
  ],
  scales: {
    x: { scale: scaleBand },
    y: { grid: true, nice: true, scale: scaleLinear },
  },
  theme: chartTheme,
  tooltip: {
    ...chartTooltip,
    // Without items, the rows are named after the channels, "x" and "y".
    items: [
      { channel: "x", label: "Month" },
      { channel: "y", label: "Revenue" },
      { id: "target", label: "Target", text: () => String(target) },
    ],
  },
});

const Example = () => (
  <div className="flex w-2xl max-w-full flex-col gap-3 p-4">
    <ChartLegend series={series} />
    <Chart
      ariaLabel="Monthly revenue against a target of 240"
      definition={definition}
      height={240}
      initialWidth={640}
    />
  </div>
);

export default Example;
";

const meta = {
  component: Chart,
  parameters: {
    docs: {
      description: {
        component: "## Structure

Charts live in `@erbium/ui/charts`, apart from the interface components. Each chart type is one file, such as `bar-chart` or `pie-chart`, built on this shared `chart` file.

| Layer         | Owner                                          | Role                                                                                                                                                   |
| ------------- | ---------------------------------------------- | ------------------------------------------------------------------------------------------------------------------------------------------------------ |
| Math          | d3 (`d3-scale`, `d3-shape`, `d3-array`)        | Scales, curves, stacks, and pie angles. Bundled inside TanStack Charts; `d3-shape` is imported directly for curves.                                    |
| Engine        | [TanStack Charts](https://tanstack.com/charts) | Compiles a chart definition of marks, channels, and scales into a scene, lays out axes, and renders SVG with focus, keyboard navigation, and tooltips. |
| Design system | `charts/chart`                                 | Erbium's palette, theme, tooltip body, HTML legend, empty state, and value formatting.                                                                 |
| Chart types   | `charts/*-chart`                               | Typed props for common charts. Each builds a definition and renders it through `Chart`.                                                                |

## Colors

Series take `--chart-1` to `--chart-6` in order: the six Vitesse accents (green, blue, cyan, orange, magenta, yellow), with separate values for light and dark themes. Give a series its own `color` to override it. `chart.css` points TanStack Charts' `--ts-chart-*` palette at the same tokens, so a hand-written definition also uses them. Past six series, group the smallest into one "Other" series.

## Shared props

Every chart type takes `ariaLabel` (required), `height`, `legend`, `tooltip`, `format` (a function from number to text; `chartNumberFormat(options, locale)` builds one from `Intl.NumberFormat` options), `locale`, and `emptyMessage`. Charts with series take `series`, an array of `{ key, label, color }`, and the legend hides and shows series with `hiddenSeries`, `defaultHiddenSeries`, and `onHiddenSeriesChange`.

## Custom charts

When no chart type fits, write a TanStack Charts definition and render it with `Chart`. Use `chartTheme` for scene colors, `chartTooltip` for the styled tooltip, and `ChartLegend` with `resolveChartSeries` for a legend.

## External documentation

TanStack Charts supplies the chart definitions, scales, marks, legends, and tooltips used in these examples.

- [TanStack Charts](https://tanstack.com/charts/latest)",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof Chart>;

export default { ...meta, title: "Charts/Chart",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "Each chart type with its default settings." },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

export const Composition: Story = {
  parameters: {
    docs: {
      description: { story: "A custom definition rendered with `Chart`: monthly revenue bars with a dashed target line. `chartTheme` and `chartTooltip` give it the same colors and tooltip as the chart types, and `ChartLegend` explains both marks.

```tsx
import {
  Chart,
  ChartLegend,
  chartTheme,
  chartTooltip,
  resolveChartSeries,
} from "@/registry/erbium/charts/chart";
import { barY, defineChart, ruleY } from "@tanstack/charts";

const definition = defineChart({
  marks: [barY(revenue, { x: "month", y: "revenue", fill: "var(--chart-1)" }), ruleY([target])],
  scales,
  theme: chartTheme,
  tooltip: chartTooltip,
});
```" },
      source: { code: CompositionSource },
    },
  },
  render: CompositionExample,
};

import type { ChartValue } from "@tanstack/charts";
import { formatChartIndex } from "@/registry/erbium/charts/chart";

export const visitors = [
  { desktop: 186, mobile: 80, month: "January" },
  { desktop: 305, mobile: 200, month: "February" },
  { desktop: 237, mobile: 120, month: "March" },
  { desktop: 73, mobile: 190, month: "April" },
  { desktop: 209, mobile: 130, month: "May" },
  { desktop: 214, mobile: 140, month: "June" },
];

export const devices = [
  { key: "desktop", label: "Desktop" },
  { key: "mobile", label: "Mobile" },
] as const;

export const shortMonth = (value: ChartValue) => formatChartIndex(value).slice(0, 3);

export const browsers = [
  { browser: "Chrome", visitors: 275 },
  { browser: "Safari", visitors: 200 },
  { browser: "Firefox", visitors: 187 },
  { browser: "Edge", visitors: 173 },
  { browser: "Other", visitors: 90 },
];

